import{_ as t,o,c as a,a2 as r}from"./chunks/framework.z3u3TMv0.js";const g=JSON.parse('{"title":"AIHubMix","description":"AIHubMix free model gateway — site entry, *-free text and image lists, Key steps, and how to fill them in MiniTavern.","frontmatter":{"title":"AIHubMix","description":"AIHubMix free model gateway — site entry, *-free text and image lists, Key steps, and how to fill them in MiniTavern.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"AIHubMix · MiniTavern Docs"}],["meta",{"property":"og:description","content":"AIHubMix free model gateway — site entry, *-free text and image lists, Key steps, and how to fill them in MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/free-cloud/aihubmix"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/free-cloud/aihubmix"}]]},"headers":[],"relativePath":"en/free-cloud/aihubmix.md","filePath":"en/free-cloud/aihubmix.md","lastUpdated":1787224147000}'),i={name:"en/free-cloud/aihubmix.md"};function d(n,e,l,s,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="aihubmix" tabindex="-1">AIHubMix <a class="header-anchor" href="#aihubmix" aria-label="Permalink to &quot;AIHubMix&quot;">​</a></h1><p>A unified <strong>OpenAI-compatible</strong> API gateway with many models; <strong>27+ models ending in <code>-free</code></strong> are platform-subsidized and free within per-model caps (usually no credit card). One Key to compare GPT / Gemini / GLM / Kimi and try free image gen. Official post: <a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">Free AI models on AIHubMix</a>.</p><blockquote><p>Quotas, model lists, and “new-user free tries” change — <strong>trust <a href="https://aihubmix.com/models" target="_blank" rel="noreferrer">aihubmix.com/models</a> and the console</strong>.</p></blockquote><h2 id="sites-and-entry-points" tabindex="-1">Sites and entry points <a class="header-anchor" href="#sites-and-entry-points" aria-label="Permalink to &quot;Sites and entry points&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Site / sign-up</td><td><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a></td></tr><tr><td>Free models post</td><td><a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">docs.aihubmix.com/cn/blogs/free-ai-models</a></td></tr><tr><td>Model plaza</td><td><a href="https://aihubmix.com/models" target="_blank" rel="noreferrer">aihubmix.com/models</a></td></tr><tr><td>Developer docs</td><td><a href="https://docs.aihubmix.com/cn" target="_blank" rel="noreferrer">docs.aihubmix.com/cn</a></td></tr><tr><td>API Base URL</td><td><code>https://aihubmix.com/v1</code></td></tr></tbody></table><h2 id="how-to-get-free-access" tabindex="-1">How to get free access <a class="header-anchor" href="#how-to-get-free-access" aria-label="Permalink to &quot;How to get free access&quot;">​</a></h2><ol><li>Open <a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a> and register with email or OAuth (officially <strong>no credit card</strong>).</li><li><strong>API Keys</strong> → create a Key (often <code>sk-…</code>).</li><li>In the model plaza filter free models and note IDs (usually end with <code>-free</code>).</li><li>In MiniTavern use <strong>Custom (OpenAI)</strong> / <strong>Custom (OpenAI Images)</strong> with Base URL + Key.</li></ol><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Free path</td><td>Model IDs with <code>-free</code>; <strong>RPM / daily token</strong> limits; quotas often reset daily (see each model page)</td></tr><tr><td>New users</td><td>Post claims limited free tries on some models after signup (e.g. GPT-5.5, GPT-Image-2); topping up unlocks more — follow the console</td></tr><tr><td>Card required</td><td>Free tier usually no</td></tr><tr><td>vs OpenRouter</td><td>OpenRouter free layer favors open-source breadth; AIHubMix stresses subsidized frontier closed-source <code>*-free</code> (e.g. GPT / Gemini free mirrors)</td></tr></tbody></table><h2 id="model-list" tabindex="-1">Model list <a class="header-anchor" href="#model-list" aria-label="Permalink to &quot;Model list&quot;">​</a></h2><p>Excerpt from the official free-models post (~2026-05); <strong>live list follows the plaza</strong>. IDs are <strong>case-sensitive</strong>.</p><h3 id="text-chat-reasoning" tabindex="-1">Text (chat / reasoning) <a class="header-anchor" href="#text-chat-reasoning" aria-label="Permalink to &quot;Text (chat / reasoning)&quot;">​</a></h3><p>Chat Completions. MiniTavern: <strong>Custom (OpenAI)</strong>.</p><h4 id="general-chat" tabindex="-1">General chat <a class="header-anchor" href="#general-chat" aria-label="Permalink to &quot;General chat&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>gpt-5.5-free</code></td><td>Flagship chat / Agent / code (platform-subsidized)</td></tr><tr><td><code>gpt-4o-free</code></td><td>Multimodal vision</td></tr><tr><td><code>gpt-4.1-free</code></td><td>Long context (~1M)</td></tr><tr><td><code>gpt-4.1-mini-free</code> / <code>gpt-4.1-nano-free</code></td><td>Speed / cost oriented</td></tr><tr><td><code>gemini-3-flash-preview-free</code></td><td>Very long context, multimodal</td></tr><tr><td><code>glm-4.7-flash-free</code></td><td>Zhipu Flash</td></tr><tr><td><code>mimo-v2-flash-free</code> / <code>ling-2.6-flash-free</code></td><td>Low-latency chat</td></tr></tbody></table><h4 id="coding-oriented" tabindex="-1">Coding-oriented <a class="header-anchor" href="#coding-oriented" aria-label="Permalink to &quot;Coding-oriented&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>coding-glm-5.1-free</code></td><td>Officially highlighted free coding tier</td></tr><tr><td><code>coding-glm-5-free</code> / <code>coding-glm-5-turbo-free</code> / <code>coding-glm-4.7-free</code>, etc.</td><td>GLM coding series</td></tr><tr><td><code>kimi-for-coding-free</code> / <code>k2.6-code-preview-free</code></td><td>Kimi coding</td></tr><tr><td><code>coding-minimax-m2-free</code> … <code>coding-minimax-m2.7-free</code></td><td>MiniMax coding series</td></tr><tr><td><code>step-3.5-flash-free</code></td><td>Lightweight completion</td></tr></tbody></table><h4 id="agent-reasoning" tabindex="-1">Agent / reasoning <a class="header-anchor" href="#agent-reasoning" aria-label="Permalink to &quot;Agent / reasoning&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>xiaomi-mimo-v2-pro-free</code></td><td>Tool calling / Agent</td></tr><tr><td><code>xiaomi-mimo-v2.5-free</code></td><td>Longer context and multi-tool calling</td></tr></tbody></table><p>For roleplay chat, try <code>gpt-4o-free</code>, <code>gemini-3-flash-preview-free</code>, or <code>glm-4.7-flash-free</code> first; coding models lean toward code completion and may not suit long stories.</p><h3 id="images-text-to-image-edit" tabindex="-1">Images (text-to-image / edit) <a class="header-anchor" href="#images-text-to-image-edit" aria-label="Permalink to &quot;Images (text-to-image / edit)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model ID</th><th>API note</th><th>App</th></tr></thead><tbody><tr><td><code>gpt-image-2-free</code></td><td><code>POST /v1/images/generations</code> (also edits)</td><td><strong>Custom (OpenAI Images)</strong></td></tr><tr><td><code>gemini-3.1-flash-image-preview-free</code> (Nano Banana 2)</td><td>Officially may use Chat Completions for chat image gen</td><td>Image link may not be compatible; prefer Images endpoint or <code>gpt-image-2-free</code></td></tr></tbody></table><h3 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h3><p>That free list focuses on <strong>LLM + image</strong>; if video exists, follow plaza labels. MiniTavern <strong>has no built-in video generation entry</strong>.</p><h2 id="how-to-fill-in-minitavern" tabindex="-1">How to fill in MiniTavern <a class="header-anchor" href="#how-to-fill-in-minitavern" aria-label="Permalink to &quot;How to fill in MiniTavern&quot;">​</a></h2><p>General steps: <a href="/ultra_guides/en/manual/model-link">Model link</a>.</p><h3 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h3><p>Path: <strong>Settings → Models → Model link → New</strong></p><ol><li>Platform: <strong>Custom (OpenAI)</strong></li><li>Base URL: <code>https://aihubmix.com/v1</code></li><li>Paste API Key</li><li>Model ID: <code>gpt-4o-free</code> or another plaza <code>*-free</code></li><li><strong>Test</strong> → on success, set as default</li></ol><h3 id="image-gen" tabindex="-1">Image gen <a class="header-anchor" href="#image-gen" aria-label="Permalink to &quot;Image gen&quot;">​</a></h3><p>Path: <strong>Settings → Image gen → Image gen link</strong></p><ol><li>Platform: <strong>Custom (OpenAI Images)</strong></li><li>Same Base URL</li><li>Same Key; model <code>gpt-image-2-free</code></li><li>Test, then use <code>/imagine</code> or image-gen entries</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ultra_guides/en/free-cloud/">Free cloud overview</a></li><li><a href="/ultra_guides/en/free-cloud/#free-image-generation">Free image gen</a></li><li><a href="/ultra_guides/en/free-cloud/opencode-zen">OpenCode Zen</a> — coding-oriented curated gateway and another Free text set</li><li><a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a></li><li><a href="/ultra_guides/en/free-cloud/openrouter">OpenRouter</a> — open-source <code>:free</code> pool</li><li><a href="/ultra_guides/en/manual/model-link">Model link</a></li></ul>',33)])])}const f=t(i,[["render",d]]);export{g as __pageData,f as default};
